import { PayButton, Switch, simulatedTask, useAsyncAction } from '${e}';
import '${e}/styles.css';

export function Checkout() {
  // PayButton takes the full state. A plain Button takes pay.visibleState.
  const pay = useAsyncAction();
  const [protection, setProtection] = useState(true);
  return (
    <section className="checkout">
      <Switch label="Shipping protection" checked={protection} onChange={setProtection} />
      <PayButton state={pay.state} onConfirm={() => void pay.run(simulatedTask(1200))}>
        Pay {protection ? '$48.99' : '$48.00'}
      </PayButton>
    </section>
  );
}
